INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65474955', 65474955, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Sewa Scenting Pengharum Ruangan Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 156000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12.0 Paket', 'Pengadaan Sewa Scenting Pengharum Ruangan pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026 dilaksanakan sebanyak 1 (satu) paket untuk jangka waktu 12 (dua belas) bulan dalam 1 (satu) Tahun Anggaran. Pekerjaan ini bertujuan untuk menunjang kenyamanan, kebersihan udara, dan kualitas lingkungan kerja perkantoran. Ruang lingkup pekerjaan meliputi penyediaan unit mesin scenting beserta cairan pewangi (refill), survei dan penentuan titik pemasangan, instalasi dan pengaturan sistem penyemprotan otomatis, pemeliharaan dan pengecekan fungsi alat secara berkala setiap bulan, penggantian refill sesuai kebutuhan, serta perbaikan atau penggantian unit apabila terjadi kerusakan selama masa kontrak. Seluruh layanan dilaksanakan secara berkesinambungan guna memastikan sistem pengharum ruangan berfungsi optimal sepanjang periode 12 bulan.', 'Spesifikasi pekerjaan Pengadaan Sewa Scenting Pengharum Ruangan sebanyak 12 paket meliputi penyediaan unit mesin scenting otomatis tipe elektrik untuk penggunaan perkantoran yang mampu beroperasi secara kontinu, dilengkapi pengaturan interval semprot (timer) yang dapat disesuaikan dengan kebutuhan ruangan dan jam operasional kantor. Mesin menggunakan cairan pewangi (refill) berkualitas, aman bagi kesehatan dan lingkungan kerja, tidak meninggalkan noda, serta memiliki daya sebar aroma yang sesuai dengan luas ruangan. Setiap paket mencakup instalasi unit pada lokasi yang telah ditentukan, pengaturan awal sistem, penggantian refill secara berkala minimal 1 (satu) kali setiap bulan atau sesuai kebutuhan pemakaian, serta pemeliharaan rutin dan pemeriksaan fungsi selama masa layanan. Penyedia wajib melakukan perbaikan atau penggantian unit apabila terjadi gangguan tanpa biaya tambahan, menjamin alat berfungsi dengan baik selama masa sewa 12 bulan, serta menyampaikan laporan pelaksanaan layanan secara berkala sebagai bentuk pertanggungjawaban pekerjaan.', 156000000, 'high', 'Sewa layanan pengharum ruangan untuk kantor pengawasan internal selama 12 bulan merupakan belanja yang tidak esensial dibanding fungsi utama organisasi. Dengan nilai anggaran penuh untuk layanan kenyamanan non-prioritas, terdapat indikasi kuat pemborosan karena manfaat publik dan urgensinya rendah.', NULL, NULL, 3, 1, 1, 1, 1, 2168538);
